  "words.special": { en: "Special moments", uk: "Особливі моменти", najdi: "المناسبات", msa: "المناسبات الخاصة" },
  "words.traps": { en: "Don't copy the internet", uk: "Не копіюй інтернет", najdi: "لا تقلّد النت", msa: "لا تقلّد الإنترنت" },
  "words.trapsSub": {
    en: "Most free Arabic online is Egyptian or Levantine, and textbooks often teach Kuwaiti (Gulf) or formal Arabic. She'll understand them, but they'll sound foreign — say it the Saudi way.",
    uk: "Більшість безкоштовної арабської в інтернеті — єгипетська або левантійська, а підручники часто вчать кувейтської (Затока) чи формальної. Вона зрозуміє, але звучатиме чужо, — кажи по-саудівськи.",
    najdi: "أغلب العربي المجاني في النت مصري أو شامي، والكتب كثير تعلّم كويتي (خليجي) أو فصحى. بتفهمه، بس بيطلع غريب — قوله على السعودي.",
    msa: "معظم العربية المجانية على الإنترنت مصرية أو شامية، وكثير من الكتب تعلّم الكويتية (الخليجية) أو الفصحى. ستفهمها، لكنها ستبدو غريبة — فقلها بالسعودية.",
  },
  "words.youSee": { en: "You'll see online", uk: "В інтернеті побачиш", najdi: "بتشوف في النت", msa: "ستراه على الإنترنت" },
